////////////////////////////////////////////////////////////////////////////////
Thread::Thread(ThreadHandle* handle) : Runnable(), properties(NULL) {

    this->properties = new ThreadProperties();
    this->properties->handle = handle;
}

////////////////////////////////////////////////////////////////////////////////
Thread::Thread() : Runnable(), properties(NULL) {
    this->initializeSelf(NULL, "", -1);
}

