Thread::Thread(Runnable* task) : Runnable(), properties(NULL) {
    this->initializeSelf(task, "", -1);
}

////////////////////////////////////////////////////////////////////////////////
Thread::Thread(const std::string& name) : Runnable(), properties(NULL) {
    this->initializeSelf(NULL, name, -1);
}

